  SuperStore.getStudyDirectoryTreeConfig = function() {
    return _hydrateConfig('cso_study_recursive_tree_v1', 'categories', () => DEFAULT_STUDY_DIRECTORY_TREE);
  };
  SuperStore.saveStudyDirectoryTreeConfig = function(cfg) {
    if (!cfg) return false;
    cfg.meta = cfg.meta || {}; cfg.meta.updatedAt = new Date().toISOString();
    cfg.categories = cfg.items || cfg.categories || []; cfg.items = cfg.categories;
    localStorage.setItem('cso_study_recursive_tree_v1', JSON.stringify(cfg));
    this.logAudit('STUDY_TREE_MUTATION', 'STUDY_LIBRARY', 'Saved study directory and content updates (' + cfg.categories.length + ' categories).');
    return true;
  };
  SuperStore.resetStudyDirectoryTreeConfig = function() {
    localStorage.setItem('cso_study_recursive_tree_v1', JSON.stringify(DEFAULT_STUDY_DIRECTORY_TREE));
    this.logAudit('STUDY_TREE_RESET', 'STUDY_LIBRARY', 'Study master directory tree reset to authentic frontend defaults.');
    return JSON.parse(JSON.stringify(DEFAULT_STUDY_DIRECTORY_TREE));
  };
  SuperStore.exportStudyDirectoryTreeManifest = function() {
    const config = this.getStudyDirectoryTreeConfig();
    const filename = "study_directory_tree_manifest_" + new Date().toISOString().slice(0, 10) + ".json";
    this.downloadJson(filename, config);
    this.logAudit("STUDY_TREE_EXPORTED", "DATA_EXPORT", "Study master directory tree manifest exported (" + filename + ").");
    return filename;
  };

  // Forwarding accessors for all 10 discrete study module routes:
